675	function validateProof(proof) {
676	  if (proof === null || typeof proof !== 'object' || Array.isArray(proof)) {
677	    return '证明文件顶层必须是 JSON 对象';
678	  }
679	  const needString = ['proofVersion', 'artifactName', 'artifactDigest', 'fileName', 'generatedAt', 'signerKeyFingerprint'];
680	  for (const k of needString) {
681	    if (typeof proof[k] !== 'string' || proof[k].length === 0) {
682	      return `证明字段缺失或类型非法: ${k}`;
683	    }
684	  }
685	  if (!/^[0-9a-f]{64}$/i.test(proof.artifactDigest)) {
686	    return '证明中的 artifactDigest 不是合法的 SHA-256 十六进制摘要';
687	  }
688	  if (!/^[0-9a-f]{64}$/i.test(proof.signerKeyFingerprint)) {
689	    return '证明中的 signerKeyFingerprint 不是合法的 SHA-256 十六进制摘要';
690	  }
691	  if (typeof proof.size !== 'number' || !Number.isFinite(proof.size) || proof.size < 0) {
692	    return '证明字段缺失或类型非法: size';
693	  }
694	  if (!Array.isArray(proof.files)) return '证明字段缺失或类型非法: files';
