698	// 清单条目校验：proof.files 与 sbom.files 共用同一套规则。
699	function validateFileEntries(files) {
700	  const seen = new Set();
701	  for (const f of files) {
702	    if (f === null || typeof f !== 'object') return '清单条目必须是对象';
703	    if (typeof f.path !== 'string' || f.path.length === 0) return '清单条目 path 非法';
704	    if (f.path.includes('\\')) return `清单相对路径必须使用正斜杠: ${f.path}`;
705	    if (f.path.startsWith('/') || f.path.split('/').includes('..')) {
706	      return `清单相对路径越界: ${f.path}`;
707	    }
708	    if (seen.has(f.path)) return `清单路径重复: ${f.path}`;
709	    seen.add(f.path);
710	    if (!/^[0-9a-f]{64}$/i.test(f.sha256)) return `清单条目摘要非法: ${f.path}`;
711	    if (typeof f.size !== 'number' || !Number.isFinite(f.size) || f.size < 0) {
712	      return `清单条目大小非法: ${f.path}`;
713	    }
714	    if (typeof f.type !== 'string' || f.type.length === 0) return `清单条目类型非法: ${f.path}`;
715	  }
716	  return null;
717	}
718	
719	function validateSbom(sbom) {
720	  if (sbom === null || typeof sbom !== 'object' || Array.isArray(sbom)) {
721	    return 'SBOM 顶层必须是 JSON 对象';
722	  }
723	  for (const k of ['schemaVersion', 'artifactName', 'rootType']) {
724	    if (typeof sbom[k] !== 'string' || sbom[k].length === 0) {
725	      return `SBOM 字段缺失或类型非法: ${k}`;
726	    }
727	  }
728	  if (!Array.isArray(sbom.files)) return 'SBOM 字段缺失或类型非法: files';
729	  return validateFileEntries(sbom.files);
730	}
