732	// 返回差异列表；每条 {path, kind}。顶层摘要差异兜底。
733	function diffManifest(proof, currentSbom, currentDigest) {
734	  const mismatches = [];
735	  const proofFiles = new Map(proof.files.map((f) => [f.path, f]));
736	  const currentFiles = new Map(currentSbom.files.map((f) => [f.path, f]));
737	
738	  for (const [path, pf] of proofFiles) {
739	    const cur = currentFiles.get(path);
740	    if (!cur) {
741	      mismatches.push({ path, kind: 'missing' }); // 证明中存在、产物中已删除
742	      continue;
743	    }
744	    if (cur.sha256.toLowerCase() !== pf.sha256.toLowerCase()) {
745	      mismatches.push({ path, kind: 'content-modified' });
746	    } else if (cur.size !== pf.size) {
747	      mismatches.push({ path, kind: 'size-mismatch' });
748	    }
749	  }
750	  for (const path of currentFiles.keys()) {
751	    if (!proofFiles.has(path)) {
752	      mismatches.push({ path, kind: 'added' }); // 产物中新出现的文件
753	    }
754	  }
755	
756	  if (proof.artifactDigest.toLowerCase() !== currentDigest.toLowerCase() && mismatches.length === 0) {
757	    // 理论上不会发生（逐文件比对已覆盖），作为顶层摘要兜底。
758	    mismatches.push({ path: '.', kind: 'artifact-digest-mismatch' });
759	  }
760	  if (proof.fileName !== currentSbom.artifactName) {
761	    mismatches.push({ path: '.', kind: 'artifact-name-mismatch' });
762	  }
763	
764	  mismatches.sort((a, b) => (a.path < b.path ? -1 : a.path > b.path ? 1 : a.kind < b.kind ? -1 : 1));
765	  return mismatches;
766	}
