772	  const proofFiles = new Map(proof.files.map((f) => [f.path, f]));
773	
774	  for (const [path, pf] of proofFiles) {
775	    const sf = sbomFiles.get(path);
776	    if (!sf) {
777	      mismatches.push({ path, kind: 'missing' }); // 证明中存在、SBOM 中缺失
778	      continue;
779	    }
780	    if (sf.sha256.toLowerCase() !== pf.sha256.toLowerCase()) {
781	      mismatches.push({ path, kind: 'content-modified' });
782	    } else if (sf.size !== pf.size) {
783	      mismatches.push({ path, kind: 'size-mismatch' });
784	    }
785	  }
786	  for (const path of sbomFiles.keys()) {
787	    if (!proofFiles.has(path)) {
788	      mismatches.push({ path, kind: 'added' }); // SBOM 中新出现的条目
789	    }
790	  }
791	  if (sbom.artifactName !== proof.artifactName) {
792	    mismatches.push({ path: '.', kind: 'artifact-name-mismatch' });
793	  }
794	
795	  mismatches.sort((a, b) => (a.path < b.path ? -1 : a.path > b.path ? 1 : a.kind < b.kind ? -1 : 1));
