918	  for (const k of ['maxFileCount', 'maxSize']) {
919	    if (policy[k] !== undefined && !isNonNegSafeInt(policy[k])) {
920	      throw new ProvError(ERROR_CODES.POLICY_INVALID, `策略字段取值非法: ${k}`);
921	    }
