944	  // 1) 时间窗口：proof.generatedAt 必须落在闭区间；字段非法单独记。
945	  const generatedAtMs = parseUtcIso(proof.generatedAt);
946	  if (generatedAtMs === null) {
947	    push('generated-at-invalid', proof.generatedAt);
948	  } else {
949	    if (policy.proofNotBefore !== undefined && generatedAtMs < parseUtcIso(policy.proofNotBefore)) {
950	      push('proof-not-before', proof.generatedAt);
951	    }
952	    if (policy.proofNotAfter !== undefined && generatedAtMs > parseUtcIso(policy.proofNotAfter)) {
953	      push('proof-not-after', proof.generatedAt);
954	    }
955	  }
956	
957	  // 2) 密钥指纹必须命中白名单（大小写不敏感）。
958	  if (policy.allowedKeyFingerprints !== undefined) {
959	    const trusted = policy.allowedKeyFingerprints.map((fp) => fp.toLowerCase());
960	    if (!trusted.includes(proof.signerKeyFingerprint.toLowerCase())) {
961	      push('allowed-key-fingerprints', proof.signerKeyFingerprint);
962	    }
963	  }
964	
965	  // 3) requireSbom：必须成对提供 --sbom/--sbom-signature；其有效性已在前面校验。
966	  //    requireSbom 为 false 时不禁用额外提供的 SBOM（沿用既有校验）。
967	  if (policy.requireSbom === true && !sbomMode) {
968	    push('require-sbom', 'absent');
969	  }
970	
971	  // 4) 文件数上限。
972	  if (policy.maxFileCount !== undefined && proof.files.length > policy.maxFileCount) {
973	    push('max-file-count', proof.files.length);
974	  }
975	
976	  // 5) 总大小上限。
977	  if (policy.maxSize !== undefined && proof.size > policy.maxSize) {
978	    push('max-size', proof.size);
979	  }
980	
981	  return violations;
982	}
983	
984	// ---------------------------------------------------------------------------
985	// CLI
986	// ---------------------------------------------------------------------------
987	
988	function parseArgs(argv) {
989	  const args = { _: [] };
990	  for (let i = 0; i < argv.length; i += 1) {
991	    const a = argv[i];
992	    if (a.startsWith('--')) {
993	      const key = a.slice(2);
994	      const next = argv[i + 1];
995	      if (next === undefined || next.startsWith('--')) {
996	        args[key] = true;
997	      } else {
998	        args[key] = next;
999	        i += 1;
1000	      }
1001	    } else {
1002	      args._.push(a);
1003	    }
1004	  }
1005	  return args;
1006	}
1007	
1008	function usage() {
1009	  return [
1010	    'Prov Guard —— 软件供应链证明与完整性校验工具',
1011	    '',
1012	    '用法:',
1013	    '  provguard keygen   --key-dir <dir> [--name <prefix>]',
1014	    '  provguard generate --artifact <path> --key <private.pem> --out <dir>',
1015	    '  provguard verify   --artifact <path> --proof <proof.json> \\',
1016	    '                      --signature <proof.json.sig> --key <public.pem> \\',
1017	    '                      [--sbom <sbom.json> --sbom-signature <sbom.json.sig>] \\',
1018	    '                      [--policy <policy.json>]',
1019	    '',
1020	    'generate 输出: proof.json / proof.json.sig / sbom.json / sbom.json.sig',
1021	    '成功状态: VERIFIED；错误码见 README。',
1022	  ].join('\n');
1023	}
1024	
1025	function printMachineError(err) {
1026	  const payload = {
1027	    status: 'ERROR',
1028	    errorCode: err instanceof ProvError ? err.code : 'INTERNAL_ERROR',
1029	    message: err && err.message ? err.message : String(err),
1030	  };
1031	  if (err && err.details !== undefined) payload.details = err.details;
1032	  return stableJsonStringify(payload);
1033	}
1034	
1035	async function main(argv) {
1036	  const args = parseArgs(argv);
1037	  const command = args._[0];
1038	
1039	  try {
1040	    if (!command || command === 'help' || command === '--help' || command === '-h') {
1041	      process.stdout.write(`${usage()}\n`);
1042	      return 0;
1043	    }
1044	
1045	    if (command === 'keygen') {
1046	      if (!args['key-dir']) {
1047	        throw new ProvError(ERROR_CODES.USAGE_ERROR, '缺少必填参数 --key-dir');
1048	      }
1049	      const r = await keygen({ keyDir: args['key-dir'], name: args.name || 'provguard' });
1050	      process.stdout.write(
1051	        `${stableJsonStringify({ status: 'KEYGEN_OK', ...r })}\n`,
1052	      );
1053	      return 0;
1054	    }
1055	
1056	    if (command === 'generate') {
1057	      const missing = ['artifact', 'key', 'out'].filter((k) => typeof args[k] !== 'string');
1058	      if (missing.length) {
1059	        throw new ProvError(
1060	          ERROR_CODES.USAGE_ERROR,
1061	          `缺少必填参数: ${missing.map((m) => `--${m}`).join(', ')}`,
1062	        );
1063	      }
1064	      const r = await generate({ artifact: args.artifact, key: args.key, out: args.out });
1065	      process.stdout.write(
1066	        `${stableJsonStringify({
1067	          status: 'GENERATED',
1068	          proofVersion: r.proofVersion,
1069	          artifactDigest: r.artifactDigest,
1070	          fileCount: r.fileCount,
1071	          proofPath: r.proofPath,
1072	          sbomPath: r.sbomPath,
1073	          signaturePath: r.signaturePath,
1074	          sbomSignaturePath: r.sbomSignaturePath,
1075	        })}\n`,
1076	      );
1077	      return 0;
1078	    }
1079	
1080	    if (command === 'verify') {
1081	      const missing = ['artifact', 'proof', 'signature', 'key'].filter((k) => typeof args[k] !== 'string');
1082	      if (missing.length) {
1083	        throw new ProvError(
1084	          ERROR_CODES.USAGE_ERROR,
1085	          `缺少必填参数: ${missing.map((m) => `--${m}`).join(', ')}`,
1086	        );
1087	      }
1088	      // --sbom 与 --sbom-signature 必须成对出现。
1089	      const hasSbom = typeof args.sbom === 'string';
1090	      const hasSbomSig = typeof args['sbom-signature'] === 'string';
1091	      if (hasSbom !== hasSbomSig) {
1092	        throw new ProvError(ERROR_CODES.USAGE_ERROR, '--sbom 与 --sbom-signature 必须成对提供');
1093	      }
1094	      // --policy 为可选单值参数；出现时必须带文件路径。
1095	      const hasPolicy = args.policy !== undefined;
1096	      if (hasPolicy && typeof args.policy !== 'string') {
1097	        throw new ProvError(ERROR_CODES.USAGE_ERROR, '--policy 需要提供策略文件路径');
1098	      }
1099	      const r = await verify({
1100	        artifact: args.artifact,
1101	        proof: args.proof,
1102	        signature: args.signature,
1103	        key: args.key,
1104	        sbom: hasSbom ? args.sbom : undefined,
1105	        sbomSignature: hasSbomSig ? args['sbom-signature'] : undefined,
1106	        policy: hasPolicy ? args.policy : undefined,
1107	      });
1108	      process.stdout.write(`${stableJsonStringify(r)}\n`);
1109	      return 0;
1110	    }
1111	
1112	    throw new ProvError(ERROR_CODES.USAGE_ERROR, `未知子命令: ${command}`);
1113	  } catch (err) {
1114	    // stderr 仅输出机器可读 JSON；用法帮助走 stdout，避免污染错误流。
1115	    process.stderr.write(`${printMachineError(err)}\n`);
1116	    if (err instanceof ProvError && err.code === ERROR_CODES.USAGE_ERROR) {
1117	      process.stdout.write(`\n${usage()}\n`);
1118	    }
1119	    return 1;
1120	  }
1121	}
1122	
1123	// 仅作为脚本直接运行时执行 main；被测试 import 时不执行。
1124	if (process.argv[1] && realpathSync(process.argv[1]) === fileURLToPath(import.meta.url)) {
1125	  main(process.argv.slice(2)).then((code) => {
1126	    process.exitCode = code;
1127	  });
1128	}
1129	
1130	export { main, ProvError, ERROR_CODES as CODES };
